def evaluate_circuit_breaker(records):
    errors = []
    for idx, r in enumerate(records):
        if r.get('id') is None:
            errors.append(f'Fila {idx}: ID nulo')
        if not (0.01 <= r.get('monto', 0) <= 10000.0):
            errors.append(f'Fila {idx}: Monto fuera de rango ({r.get("monto")})')

    if errors:
        raise ValueError(f'CIRCUIT BREAKER ACTIVADO: {len(errors)} anomalias detectadas.')
    return 'CALIDAD CERTIFICADA'

batch_valido = [{'id': 1, 'monto': 50.0}, {'id': 2, 'monto': 120.0}]
batch_corrupto = [{'id': 3, 'monto': -5.0}]

print('Batch 1:', evaluate_circuit_breaker(batch_valido))
try:
    evaluate_circuit_breaker(batch_corrupto)
except ValueError as e:
    print('Batch 2:', str(e))
